void dei_out_comfort_closure ( void  *payload )
{
	if(dei_feature_get(DEI_FEAT_COMFORT_CLOSURE)==2) {
		DEI_OUT_COMFORT_CLOSURE( 1  , COMFORT_PULSE_LENGTH , 1  , 1 );
	}
	else if(dei_feature_get(DEI_FEAT_COMFORT_CLOSURE)==3){
		DEI_OUT_COMFORT_CLOSURE( 80  , COMFORT_PULSE_LENGTH , 1  , 1 );
	}
}

